{
  "tasks": [
    {
      "task_id": "T1",
      "title": "本科岗位各城市薪资中位数比较",
      "business_question": "只看本科岗位，按城市比较薪资元的中位数是多少？",
      "priority": "P0",
      "priority_reason": "直接回答核心业务目标：在限定学历为本科的前提下，对比不同城市的薪资中位数水平。删除此任务将无法完成核心分析。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "eq",
                "value": "本科"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "median",
                "field": "field_0003",
                "alias": "salary_median"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        }
      ]
    }
  ]
}
